'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var ln = require( '@stdlib/math/base/special/ln' );
var pow = require( '@stdlib/math/base/special/pow' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var LN_SQRT_TWO_PI = require( '@stdlib/constants/float64/ln-sqrt-two-pi' );


// VARIABLES //

var LN_SQRT2 = 0.34657359027997265; // ln(sqrt(2))


// MAIN //

/**
* Returns a function for evaluating the natural logarithm of the probability density function (PDF) for a half-normal distribution.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} function to evaluate the natural logarithm of the probability density function
*
* @example
* var logpdf = factory( 2.0 );
* var y = logpdf( 1.0 );
* // returns -1.0439385332046727
*
* y = logpdf( 0.0 );
* // returns -0.9189385332046727
*/
function factory( sigma ) {
	var s2;
	var A;
	if (
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( sigma === 0.0 ) {
		return logpdf;
	}
	s2 = pow( sigma, 2.0 );
	A = LN_SQRT2 - ln( sigma ) - LN_SQRT_TWO_PI + ( 0.5 * ln( 2.0 ) );
	return logpdf;

	/**
	* Evaluates the natural logarithm of the probability density function (PDF) for a half-normal distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated natural logarithm of PDF
	*
	* @example
	* var y = logpdf( 2.0 );
	* // returns <number>
	*/
	function logpdf( x ) {
		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x < 0.0 ) {
			return NINF;
		}
		if ( sigma === 0.0 ) {
			return ( x === 0.0 ) ? PINF : NINF;
		}
		return A - ( pow( x, 2.0 ) / ( 2.0 * s2 ) );
	}
}


// EXPORTS //

module.exports = factory;
